//! The `connections` table, as generated by Go `orm.GenerateTableSchema` for
//! `netquery.Conn`.

/// SQLite storage class of a column.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ColumnKind {
    Text,
    Integer,
    Float,
    Blob,
    /// Go maps bool to sqlite's null type, which renders as an empty type name.
    Bool,
}

/// One column definition.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Column {
    pub name: &'static str,
    pub kind: ColumnKind,
    pub primary: bool,
    pub nullable: bool,
    pub is_time: bool,
    /// VARCHAR length for text columns, 0 if unset.
    pub length: u16,
    pub default_int: Option<i64>,
}

const fn col(name: &'static str, kind: ColumnKind) -> Column {
    Column {
        name,
        kind,
        primary: false,
        nullable: false,
        is_time: false,
        length: 0,
        default_int: None,
    }
}

const fn nullable(mut c: Column) -> Column {
    c.nullable = true;
    c
}

const fn varchar(mut c: Column, len: u16) -> Column {
    c.length = len;
    c
}

const fn time(mut c: Column) -> Column {
    c.is_time = true;
    c
}

const fn default0(mut c: Column) -> Column {
    c.default_int = Some(0);
    c
}

use ColumnKind::{Blob, Bool, Float, Integer, Text};

/// Columns in Go struct order.
pub const CONNECTIONS: &[Column] = &[
    Column {
        primary: true,
        ..col("id", Text)
    },
    col("profile", Text),
    col("path", Text),
    varchar(col("type", Text), 8),
    col("external", Bool),
    col("ip_version", Integer),
    col("ip_protocol", Integer),
    col("local_ip", Text),
    col("local_port", Integer),
    col("remote_ip", Text),
    col("remote_port", Integer),
    col("domain", Text),
    varchar(col("country", Text), 2),
    col("asn", Integer),
    col("as_owner", Text),
    col("latitude", Float),
    col("longitude", Float),
    col("scope", Integer),
    col("worst_verdict", Integer),
    col("verdict", Integer),
    col("firewall_verdict", Integer),
    time(col("started", Text)),
    nullable(time(col("ended", Text))),
    col("tunneled", Bool),
    col("encrypted", Bool),
    col("internal", Bool),
    col("direction", Text),
    col("extra_data", Blob),
    nullable(col("allowed", Bool)),
    col("profile_revision", Integer),
    nullable(col("exit_node", Text)),
    default0(col("bytes_received", Integer)),
    default0(col("bytes_sent", Integer)),
    col("active", Bool),
    col("profile_name", Text),
];

/// Returns the column definition by name.
pub fn column(name: &str) -> Option<&'static Column> {
    CONNECTIONS.iter().find(|c| c.name == name)
}

impl Column {
    /// Go `ColumnDef.AsSQL`.
    pub fn as_sql(&self) -> String {
        let mut sql = format!("{} ", self.name);
        sql += &match (self.kind, self.length) {
            (Text, len) if len > 0 => format!("VARCHAR({len})"),
            (Text, _) => "TEXT".to_string(),
            (Integer, _) => "INTEGER".to_string(),
            (Float, _) => "REAL".to_string(),
            (Blob, _) => "BLOB".to_string(),
            (Bool, _) => String::new(),
        };
        if self.primary {
            sql += " PRIMARY KEY";
        }
        if let Some(default) = self.default_int {
            sql += &format!(" DEFAULT {default} ");
        }
        if !self.nullable {
            sql += " NOT NULL";
        }
        sql
    }
}

/// Go `TableSchema.CreateStatement` for the connections table.
pub fn create_statement(database: &str, if_not_exists: bool) -> String {
    let mut sql = "CREATE TABLE".to_string();
    if if_not_exists {
        sql += " IF NOT EXISTS";
    }
    let name = if database.is_empty() {
        "connections".to_string()
    } else {
        format!("{database}.connections")
    };
    let cols: Vec<String> = CONNECTIONS.iter().map(Column::as_sql).collect();
    format!("{sql} {name} ( {} );", cols.join(", "))
}
